/// AC1): the wrapper argv then carries only `. "$1"` + the path — the
/// script body (with any `pkill -f` pattern) never lands in
/// /proc/<pid>/cmdline. The dir is deleted by the caller once the process
/// exits. Null on any failure → the legacy `sh -c <command>` delivery.
static Future<Directory?> _writeGuardedScript(String command) async {
 try {
   final dir = await Directory.systemTemp.createTemp('fa_sh_cmd_');
   try {
     await File('${dir.path}/cmd.sh')
         .writeAsString('${bashGuardPrelude()}\n$command\n');
   } on Object {
     try { dir.deleteSync(recursive: true); } on Object {}
     return null;
   }
   return dir;
 } on Object {
   return null;
 }
