      Process.runSync('chmod', ['000', locked]);
      try {
        final result = await fs.readTextFile('locked.txt');
        expect(result.errorOrNull?.code, FileErrorCode.permissionDenied);
      } finally {
        Process.runSync('chmod', ['644', locked]);
      }
