        final result = await tool.execute(
          {'command': 'pkill -f fa_self_match_tok_1763; echo survived'},
          null,
          null,
        );
        final text = result.content
            .whereType<TextContent>()
            .map((c) => c.text)
            .join('\n');
        expect(text, contains('survived'));
        expect(text, isNot(contains('-15')));
      },
