        final job = jobResult.getOrThrow();
        await job.settled;
        // Pre-fix the job's own wrapper died by SIGTERM (exit -15).
        expect(job.exitCode, 0, reason: 'background job shell self-killed');
        expect(
          File(job.logPath).readAsStringSync(),
          contains('survived'),
