              '(exit $exec); the script body must never ride the wrapper '
              'argv',
        );
        expect(exec.stdout, contains('survived'));
      },
    );

    test(
      'pgrep -f does not list its own bash tool shell',
      skip: Platform.isWindows ? 'POSIX process semantics only' : false,
