          options: ShellExecOptions(
            env: {'FA_PROTECTED_PIDS': '${protectedDummy.pid}'},
          ),
        );
        final stdout = result.getOrThrow().stdout;
        expect(stdout, contains('protected_alive'),
            reason: 'a pid on FA_PROTECTED_PIDS must never be signaled');
