    _psOutput(['-ax', '-o', 'pid=,lstart=']);

/// The raw `ps -ax -o pid=,pgid=` stdout, or null when ps fails.
Future<String?> processGroupTableSnapshot() =>
    _psOutput(['-ax', '-o', 'pid=,pgid=']);

/// The raw `ps -o lstart= -p <pid>` stdout, or null when ps fails or
